"""Curated Phase 6 batch 1. Run from project root."""
import json, pathlib, re
P=pathlib.Path('data')
def add(name,rows):
 path=P/(name+'.json'); data=json.loads(path.read_text()); keys={json.dumps({k:v for k,v in r.items() if k not in ('id','source','verified','editorialStatus','familyFriendly','review')},sort_keys=True).casefold() for r in data}; ids={r['id'] for r in data}
 new=[]
 for r in rows:
  key=json.dumps({k:v for k,v in r.items() if k not in ('id','source','verified','editorialStatus','familyFriendly','review')},sort_keys=True).casefold()
  if key in keys or r['id'] in ids: continue
  keys.add(key);ids.add(r['id']);new.append(r)
 data+=new;path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n');print(name,len(new),len(data))
 return new

